async function boot(){const canvas=document.querySelector('canvas'),loading=document.querySelector('#loading'),notice=document.querySelector('#notice');try{const paint=graphics(canvas);const response=await fetch(new URL('./mall_action.aba967c9dc10.wasm',import.meta.url));if(!response.ok)throw Error('Could not load Rust game');const {instance}=await WebAssembly.instantiate(await response.arrayBuffer(),{});const wasm=instance.exports;const params=new URLSearchParams(location.search);const seed=Number(params.get('seed')??Date.now())>>>0;const debug=params.get('debug')==='1';wasm.init(seed,debug?1:0,params.get('gallery')==='1'?1:0);const input=new Input,clock=new FixedLoop,audio=new AudioEngine;let crt=true;try{crt=localStorage.getItem('mall-rust-crt')!=='off';}catch{}let frozen=false;let toastTimer;const toast=s=>{notice.textContent=s;notice.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.style.display='none',1500)};const state=()=>{const names=['scene','x','y','floor','score','lives','packages','loop','continues','lift','paused','map','frames','store','search','enemies','highScore','alarm','invulnerability','rng','armor','radar','blackFriday','stun','bonusTrack','fallingLamps'];return Object.fromEntries(names.map((n,i)=>[n,wasm.game_read(i)]))};const render=t=>{const ptr=wasm.draw();paint(new Uint8Array(wasm.memory.buffer,ptr,256*240*4),crt,t)};const sounds=()=>{for(let i=0;i<64;i++){const s=wasm.sound();if(!s)break;audio.fx(s)}};function resize(){const scale=Math.max(1,Math.floor(Math.min(innerWidth/256,innerHeight/240)));canvas.width=256*scale;canvas.height=240*scale;canvas.style.width=canvas.width+'px';canvas.style.height=canvas.height+'px';render(performance.now())}addEventListener('resize',resize);addEventListener('keydown',e=>{const mapped=mapKey(e.key,e.code);if(mapped)e.preventDefault();audio.start();const bit=input.down(e.key,e.code,e.repeat);if(bit===256){crt=!crt;try{localStorage.setItem('mall-rust-crt',crt?'on':'off')}catch{}toast(crt?'CRT ON':'CRT OFF')}if(bit===512){audio.mute=!audio.mute;toast(audio.mute?'SOUND OFF':'SOUND ON')}});addEventListener('keyup',e=>input.up(e.code));addEventListener('blur',()=>{input.clear();clock.reset()});document.addEventListener('visibilitychange',()=>{input.clear();clock.reset()});addEventListener('gamepadconnected',()=>audio.start());canvas.addEventListener('pointerdown',()=>{audio.start();canvas.focus();input.queue.push(128)});loading.remove();canvas.focus();resize();if(debug){window.game={get state(){return state()},get fixtures(){return Array.from({length:8},(_,i)=>({x:wasm.fixture_read(i,0),y:wasm.fixture_read(i,1),content:wasm.fixture_read(i,2),open:!!wasm.fixture_read(i,3)}))},get audio(){return audio.status()},get crt(){return crt},step(n,buttons=0){for(let i=0;i<n;i++)wasm.tick(buttons,i===0?buttons:0);render(performance.now());sounds();return state()},command(op,a=0,b=0){wasm.debug_command(op,a,b);render(performance.now());return state()},freeze(v=true){frozen=v;clock.reset()},buttons:PAD,wasm};}const animate=t=>{if(!document.hidden&&!frozen){input.poll(navigator.getGamepads?.());clock.advance(t,()=>{const edge=input.edge();wasm.tick(input.held()|(edge&255),edge&255)});sounds();audio.music(state())}render(t);requestAnimationFrame(animate)};requestAnimationFrame(animate);}catch(err){canvas.style.display='none';loading.textContent=String(err.message??err);console.error(err)}}
